// Turns the .sql files into a TypeScript module.
//
// The browser has no filesystem, so the demo cannot read supabase/migrations
// the way the node tests do. Generating one module keeps a single ordered
// source of truth for both: tests and the browser apply exactly the same SQL,
// in exactly the same order, or the generated file is stale and CI says so.

import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(here, "..");
const migrationsDir = path.join(root, "supabase", "migrations");
const shimPath = path.join(root, "tests", "supabase-shim.sql");
const outPath = path.join(root, "src", "migrations.generated.ts");

const literal = (sql) => "`" + sql.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${") + "`";

const files = (await readdir(migrationsDir)).filter((f) => f.endsWith(".sql")).sort();

const parts = [
  "// GENERATED by scripts/build-migrations.mjs — do not edit.",
  "// Run `corepack pnpm --filter @clinic/db run generate` after changing any .sql file.",
  "",
  "export interface Migration {",
  "  name: string;",
  "  sql: string;",
  "}",
  "",
  "/** Stand-in for the parts of a real Supabase project our SQL assumes. Never ships. */",
  `export const SUPABASE_SHIM = ${literal(await readFile(shimPath, "utf8"))};`,
  "",
  "/** Every migration, in the order Postgres must see them. */",
  "export const MIGRATIONS: Migration[] = [",
];

for (const file of files) {
  const sql = await readFile(path.join(migrationsDir, file), "utf8");
  parts.push(`  { name: ${JSON.stringify(file)}, sql: ${literal(sql)} },`);
}
parts.push("];", "");

await writeFile(outPath, parts.join("\n"));
console.log(`wrote ${path.relative(root, outPath)}: shim + ${files.length} migration(s)`);
